        BigDecimal totalFinal = Dinheiro.centavos(totalFinal(totalPedido, parcelas));
        return new ResultadoPagamento(totalFinal, parcelas,
                Dinheiro.dividir(totalFinal, parcelas),
                totalFinal.subtract(totalPedido));
