  static BigDecimal[] price(BigDecimal total,int n){
    BigDecimal i=new BigDecimal("0.0199");
    BigDecimal c=BigDecimal.ONE.add(i).pow(n);
    BigDecimal f=i.multiply(c).divide(c.subtract(BigDecimal.ONE), MathContext.DECIMAL128);
    BigDecimal p=total.multiply(f).setScale(2,RoundingMode.HALF_EVEN);
    return new BigDecimal[]{p,p.multiply(BigDecimal.valueOf(n))};
  }
  public static void main(String[] a){
    for(int n: new int[]{4,6,12}){
      System.out.println(n+" 101.00 -> "+price(new BigDecimal("101.00"),n)[0]+" / "+price(new BigDecimal("101.00"),n)[1]);
      System.out.println(n+" 431.45 -> "+price(new BigDecimal("431.45"),n)[0]+" / "+price(new BigDecimal("431.45"),n)[1]);
    }
    System.out.println(new BigDecimal("298.50").multiply(new BigDecimal("0.01")).setScale(2,RoundingMode.HALF_EVEN));
    System.out.println(new BigDecimal("299.50").multiply(new BigDecimal("0.01")).setScale(2,RoundingMode.HALF_EVEN));
    System.out.println(new BigDecimal("298.50").multiply(new BigDecimal("0.02")).setScale(2,RoundingMode.HALF_EVEN));
  }
}
